Console.WriteLine("Repository lookup: Product? for not found");
Console.WriteLine("Reservation attempt: bool for accepted or rejected");
Console.WriteLine("Payment decision: PaymentResult for expected details");
Console.WriteLine("Invalid operation: exception for a broken usage rule");
Console.WriteLine("API mapping: 404 or 409 for transport");
Console.WriteLine("UI mapping: readable message for a person");
Console.WriteLine(FindProduct(7)?.Name ?? "Not found");
Console.WriteLine($"Reserved: {TryReserve(2)}");
Console.WriteLine(Authorize(125m).Message);

Product? FindProduct(int id) => id == 7 ? new Product(7, "Notebook") : null;
bool TryReserve(int quantity) => quantity > 0 && quantity <= 5;
PaymentResult Authorize(decimal amount) => amount <= 100m
    ? new(true, "Approved")
    : new(false, "Limit exceeded");

sealed record Product(int Id, string Name);
sealed record PaymentResult(bool Succeeded, string Message);
